/* Real uploads for explicitly Standard conversations. Matrix media stays separate. */
(() => {
 'use strict';
 let active=null;
 const accept='image/png,image/jpeg,image/webp,application/pdf,text/plain,audio/webm,audio/ogg,audio/mp4';
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function stopTracks(state){state.stream?.getTracks().forEach(track=>track.stop());state.stream=null;clearInterval(state.timer);state.timer=null;}
 function dispose(state=active){if(!state||state.disposed)return;state.disposed=true;state.observer?.disconnect();if(state.recorder?.state!=='inactive')try{state.recorder.stop();}catch{}stopTracks(state);if(state.previewURL)URL.revokeObjectURL(state.previewURL);state.previewURL=null;if(state.asset&&!state.queued&&state.context.isCurrent())state.context.request('/api/media/'+state.asset.id+'/cancel',{}).catch(()=>{});if(active===state)active=null;}
 function current(state){return !state.disposed&&active===state&&state.context.isCurrent()&&state.root?.isConnected;}
 function message(state,text,error=false){const node=state.root?.querySelector('[data-vn-status]');if(node){node.textContent=text;node.classList.toggle('vn-error',error);}}
 function review(state){if(!current(state))return;const root=state.root,preview=root.querySelector('[data-vn-preview]');if(state.previewURL)URL.revokeObjectURL(state.previewURL);state.previewURL=URL.createObjectURL(state.file);const mime=state.file.type.split(';')[0];preview.innerHTML=`<strong>${esc(state.file.name||'Voice recording')}</strong><span>${(state.file.size/1024).toFixed(1)} KiB · ${esc(mime)}</span>${mime.startsWith('image/')?`<img src="${state.previewURL}" alt="Selected image preview">`:mime.startsWith('audio/')?`<audio controls preload="metadata" src="${state.previewURL}" aria-label="Review voice recording"></audio>`:''}`;root.querySelector('[data-vn-upload]').disabled=false;root.querySelector('[data-vn-send]').disabled=true;message(state,'Ready to upload. This file is not sent yet.');}
 async function select(state,file){if(!current(state)||!file||state.busy)return;const serial=state.selection=(state.selection||0)+1;state.root.querySelector('[data-vn-upload]').disabled=true;state.root.querySelector('[data-vn-send]').disabled=true;message(state,'Checking the selected file…');try{if(file.size<1||file.size>8*1024*1024)throw Error('Choose a file smaller than 8 MiB.');const mime=file.type.split(';')[0];if(!accept.split(',').includes(mime))throw Error('Use PNG, JPEG, WebP, PDF, text, or a supported voice recording.');if(mime.startsWith('image/'))window.VoidMediaValidation.inspectImage(new Uint8Array(await file.arrayBuffer()));if(!current(state)||state.selection!==serial)return;state.cancelRecording?.();if(state.asset)state.context.request('/api/media/'+state.asset.id+'/cancel',{}).catch(()=>{});state.file=file;state.asset=null;state.clientId=crypto.randomUUID();review(state);}catch(error){if(current(state)&&state.selection===serial){message(state,error.message,true);state.root.querySelector('[data-vn-upload]').disabled=!state.file;state.root.querySelector('[data-vn-send]').disabled=!state.asset;}}}
 async function upload(state){if(!current(state)||state.busy||!state.file)return;state.busy=true;const button=state.root.querySelector('[data-vn-upload]');button.disabled=true;state.root.querySelector('[data-vn-file]')?.setAttribute('disabled','');message(state,'Uploading… wait for the server acknowledgment.');try{
  const asset=await window.VoidProfileMedia.upload({request:state.context.request,blob:state.file,filename:state.file.name||'voice.webm',kind:state.kind,clientId:state.clientId,conversationId:state.context.conversationId,channelId:state.context.channelId,isCurrent:()=>!state.disposed&&state.context.isCurrent()});
  if(!current(state)){if(state.context.isCurrent())state.context.request('/api/media/'+asset.id+'/cancel',{}).catch(()=>{});return;}state.asset=asset;state.root.querySelector('[data-vn-send]').disabled=false;message(state,'Upload acknowledged. Review the recipient and choose Add to outbox.');button.textContent='Uploaded';
 }catch(error){if(current(state)){message(state,error.message||'Upload failed. Retry keeps the same file ID.',true);button.disabled=false;}}finally{state.busy=false;if(current(state))state.root.querySelector('[data-vn-file]')?.removeAttribute('disabled');}}
 async function send(state){if(!current(state)||!state.asset||state.busy)return;state.busy=true;state.queued=true;const button=state.root.querySelector('[data-vn-send]');button.disabled=true;try{const caption=state.root.querySelector('[data-vn-caption]').value;await state.context.enqueueAttachment(state.asset,caption);if(current(state)){state.context.announce('Attachment added to the conversation outbox.');state.context.closeDialog();}dispose(state);}catch(error){state.queued=false;if(current(state)){message(state,error.message||'The file could not be queued. Retry it here.',true);button.disabled=false;}}finally{state.busy=false;}}
 async function record(state){if(!current(state)||state.busy||state.recorder?.state==='recording')return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){message(state,'Voice recording is unavailable in this browser. Upload a supported audio file instead.',true);return;}
  const type=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(value=>MediaRecorder.isTypeSupported(value));if(!type){message(state,'This browser has no supported recording format. Upload an audio file instead.',true);return;}
  message(state,'Waiting for microphone permission…');let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!current(state)){stream.getTracks().forEach(track=>track.stop());return;}state.stream=stream;const chunks=[];let size=0,tooLarge=false,cancelled=false,started=Date.now(),seconds=0;const recorder=new MediaRecorder(stream,{mimeType:type});state.recorder=recorder;state.cancelRecording=()=>{cancelled=true;if(recorder.state!=='inactive')recorder.stop();stopTracks(state);};
   recorder.addEventListener('dataavailable',event=>{if(!event.data.size)return;size+=event.data.size;if(size>8*1024*1024){tooLarge=true;if(recorder.state!=='inactive')recorder.stop();return;}chunks.push(event.data);});
   recorder.addEventListener('error',()=>{cancelled=true;stopTracks(state);if(current(state))message(state,'Recording stopped. The microphone is released; try again.',true);});
   recorder.addEventListener('stop',()=>{stopTracks(state);if(!current(state))return;state.root.querySelector('[data-vn-record]').disabled=false;state.root.querySelector('[data-vn-stop]').disabled=true;state.root.querySelector('[data-vn-cancel-recording]').disabled=true;if(cancelled){message(state,'Recording discarded.');return;}if(tooLarge){message(state,'Recording exceeded 8 MiB and was discarded. Record a shorter note.',true);return;}const mime=type.split(';')[0],file=new File(chunks,['voice',mime==='audio/ogg'?'ogg':mime==='audio/mp4'?'m4a':'webm'].join('.'),{type:mime});select(state,file);});
   recorder.start(250);state.root.querySelector('[data-vn-record]').disabled=true;state.root.querySelector('[data-vn-stop]').disabled=false;state.root.querySelector('[data-vn-cancel-recording]').disabled=false;message(state,'Recording · 0:00');state.timer=setInterval(()=>{if(!current(state)){state.cancelRecording();return;}seconds=Math.floor((Date.now()-started)/1000);message(state,`Recording · ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`);if(seconds>=120&&recorder.state!=='inactive')recorder.stop();},1000);
  }catch(error){stream?.getTracks().forEach(track=>track.stop());stopTracks(state);if(current(state))message(state,error.name==='NotAllowedError'?'Microphone access was denied. You can upload an audio file instead.':'The microphone could not start. Check device access and retry.',true);}
 }
 function open(context){
  if(!context?.accountId||!context.isCurrent?.()||!!context.conversationId===!!context.channelId||!(/^[a-f0-9-]{36}$/i.test(context.conversationId||context.channelId||'')))throw Error('Choose one Standard conversation before attaching a file.');dispose();
  const kind=context.kind==='voice'?'voice':'attachment',state={context,kind,asset:null,file:null,clientId:null,busy:false,queued:false,disposed:false};active=state;
  context.showDialog(kind==='voice'?'Voice note':'Add a file','Standard conversation · uploaded files and recordings are stored by the service and are not end-to-end encrypted.',`<section class="vn-media" id="vn-media"><p class="vn-destination">Destination: ${context.channelId?'current community channel':'current conversation'}. The attachment keeps this destination if you navigate away.</p>${kind==='voice'?'<div class="vn-record-controls"><button class="vh-secondary" type="button" data-vn-record>Record voice note</button><button class="vh-secondary" type="button" data-vn-stop disabled>Stop and review</button><button class="vh-secondary" type="button" data-vn-cancel-recording disabled>Discard recording</button></div><p class="vn-fine">Microphone access starts when you choose Record. Limit: 2 minutes and 8 MiB.</p>':''}<label class="vp-file-label vh-secondary">Choose ${kind==='voice'?'audio':'file'}<input type="file" data-vn-file accept="${kind==='voice'?'audio/webm,audio/ogg,audio/mp4':accept}"></label><p class="vn-fine">Up to 8 MiB. PNG, JPEG, still WebP, PDF, UTF-8 text and supported audio. File content and filename are service-readable.</p><div class="vn-preview" data-vn-preview></div><label class="vh-field">Optional message<textarea data-vn-caption rows="2" maxlength="4000" placeholder="Add context for this file"></textarea></label><p class="vn-status" data-vn-status role="status">Choose a file to begin.</p><div class="vn-actions"><button class="vh-secondary" type="button" data-vn-upload disabled>Upload file</button><button class="vh-primary" type="button" data-vn-send disabled>Add to outbox</button><button class="vh-secondary" type="button" data-vn-cancel>Cancel</button></div></section>`);
  state.root=document.getElementById('vn-media');if(!state.root){dispose(state);return;}state.root.addEventListener('change',event=>{if(event.target.hasAttribute('data-vn-file'))select(state,event.target.files?.[0]);});state.root.addEventListener('click',event=>{if(event.target.closest('[data-vn-upload]'))upload(state);else if(event.target.closest('[data-vn-send]'))send(state);else if(event.target.closest('[data-vn-record]'))record(state);else if(event.target.closest('[data-vn-stop]'))state.recorder?.stop();else if(event.target.closest('[data-vn-cancel-recording]'))state.cancelRecording?.();else if(event.target.closest('[data-vn-cancel]')){dispose(state);context.closeDialog();}});
  if(window.MutationObserver){state.observer=new MutationObserver(()=>{const dialog=state.root?.closest('dialog');if(!state.root.isConnected||(dialog&&!dialog.open)||!context.isCurrent())dispose(state);});state.observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});}
 }
 const extension={id:'native-media',onLock(){dispose();}};
 function register(){window.VoidHome?.registerExtension?.(extension);}window.addEventListener('voidline:home-ready',register,{once:true});register();
 window.VoidNativeMedia=Object.freeze({open,dispose});
})();
